// File: tage_u_counter_attack.c

#include <stdint.h> // For uint64_t
#include <stdio.h>  // For printf

// Standard boilerplate (stack, tohost, trap handler)
uint64_t _stack[512];
uint64_t * const _stack_top = _stack+512;
extern volatile uint64_t tohost;

void handle_trap() __attribute__((naked));
void handle_trap() {
    // Save context (minimal for this experiment)
    asm volatile(
        "csrrw sp, mscratch, sp\n" // Swap to M-mode stack
        "addi sp, sp, -16\n"       // Allocate space for ra and sp
        "sd ra, 0(sp)\n"
        "sd sp, 8(sp)\n"
    );

    // Determine trap cause and handle
    uintptr_t mcause, mepc;
    asm volatile("csrr %0, mcause" : "=r"(mcause));
    asm volatile("csrr %0, mepc" : "=r"(mepc));

    // Handle ECALL (Machine-mode Environment Call) by advancing mepc
    if (mcause == 11) { // Machine ECALL
        mepc += 4;
        asm volatile("csrw mepc, %0" :: "r"(mepc));
    } else {
        // For any other trap, print cause and terminate (or loop indefinitely)
        // In a real system, you'd have a more robust error handling
        printf("Unhandled trap! mcause: %lu, mepc: %lu\n", mcause, mepc);
        tohost = 1; // Signal simulation termination
        while(1);
    }

    // Restore context and return
    asm volatile(
        "ld sp, 8(sp)\n"
        "ld ra, 0(sp)\n"
        "addi sp, sp, 16\n"
        "csrrw sp, mscratch, sp\n" // Swap back to original stack
        "mret\n"
    );
}

void _start() {
    asm volatile("mv sp, %0" :: "r"(_stack_top));
    // Set up trap handler (Machine Trap-Vector Base-Address Register)
    asm volatile("csrw mtvec, %0" :: "r"(&handle_trap));

    // Set M-mode stack pointer to mscratch for trap handler
    asm volatile("csrw mscratch, %0" :: "r"(_stack_top - 512)); // A separate, safe M-mode stack

    extern int main(); // Declare main to avoid implicit declaration warning
    main();

    // Terminate simulation
    tohost = 1;
    while (1) {}
}

// Define experiment parameters
#define N_TRIALS 20
#define N_DECREMENT 4 // For a 2-bit u-counter, 2 mispredictions should zero it. Use 4 for safety.
#define N_TRAIN_INITIAL 16 // To ensure the u-counter is fully incremented initially.

// Array to store results
uint64_t results_neg_control[N_TRIALS];
uint64_t results_pos_control[N_TRIALS];
uint64_t pc_predicted_taken[N_TRIALS];
uint64_t pc_mispredicted_not_taken[N_TRIALS];


// Function containing the target branch
// This function must be in .text and have a stable PC for the branch.
// We are assuming that this function will consistently map to the same TAGE entry
// when called in a similar GHR context.
__attribute__ ((noinline)) // Prevent inlining to keep a stable PC for target_branch_func
void target_branch_func(int condition) {
    // Add some NOPs to ensure the branch instruction itself takes time
    // and to separate it from other instructions.
    asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
    if (condition) {
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
    } else {
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
    }
    asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
}

// De-train the u-counter for target_branch_func
// This function ensures the u-counter for target_branch_func is brought to 0.
__attribute__ ((noinline))
void de_train_u_counter() {
    // Phase 1: Train the branch to consistently predict TAKEN.
    // This will bring its u-counter to maximum value (e.g., 2 for 2-bit counter).
    for (int i = 0; i < N_TRAIN_INITIAL; i++) {
        target_branch_func(1); // Force taken
    }
    // Phase 2: Force MISPREDICTIONS.
    // By calling target_branch_func with 'condition=0', we force the branch to NOT TAKEN.
    // If the predictor is still biased towards TAKEN, this will cause mispredictions,
    // decrementing the u-counter. After N_DECREMENT mispredictions, the u-counter
    // should be at 0.
    for (int i = 0; i < N_DECREMENT; i++) {
        target_branch_func(0); // Force not taken. This will likely be mispredicted.
    }
}

// Probe for timing of target_branch_func
// This measures the cost of a single execution of target_branch_func
// with a condition that is expected to be correctly predicted if the u-counter
// is high (i.e., not primed for eviction/re-training).
__attribute__ ((noinline))
uint64_t probe_target_branch() {
    uint64_t start_cycle, end_cycle;
    // Ensure pipeline is settled before measuring
    asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");

    // Read cycle counter
    asm volatile ("rdcycle %0" : "=r" (start_cycle));

    // Execute the target branch with a 'taken' outcome.
    // The timing of this execution reveals the state of its TAGE entry's u-counter.
    target_branch_func(1); 

    // Read cycle counter again
    asm volatile ("rdcycle %0" : "=r" (end_cycle));
    return end_cycle - start_cycle;
}

// Victim's actions - does not touch the target branch (Negative Control)
__attribute__ ((noinline))
void victim_do_nothing() {
    // Simulate some work without touching the target branch.
    // This ensures the TAGE entry's u-counter remains at 0 if de-trained.
    for (int i = 0; i < 100; i++) { // Small loop to simulate some activity
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;");
    }
}

// Victim's actions - executes the target branch once (Positive Control / Attack path)
__attribute__ ((noinline))
void victim_execute_branch_once() {
    // Execute the target branch once with a 'taken' outcome.
    // This should increment the u-counter from 0 back up.
    target_branch_func(1); 
}


int main() {
    printf("TAGE U-Counter Manipulation Experiment\n");
    printf("N_TRIALS: %lu, N_DECREMENT: %lu, N_TRAIN_INITIAL: %lu\n", (uint64_t)N_TRIALS, (uint64_t)N_DECREMENT, (uint64_t)N_TRAIN_INITIAL);

    // --- Positive Control: Branch Prediction Baseline ---
    // This section verifies that the measurement setup can differentiate
    // between correctly predicted and mispredicted branches.
    printf("\n--- Positive Control: Branch Prediction Baseline ---\n");
    printf("Training branch to predict taken. Measuring correct vs misprediction.\n");

    for (int i = 0; i < N_TRIALS; i++) {
        // Train branch to always predict TAKEN
        for (int j = 0; j < N_TRAIN_INITIAL; j++) {
            target_branch_func(1); // Force taken
        }

        uint64_t start, end;
        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;"); // Pipeline settle
        asm volatile ("rdcycle %0" : "=r" (start));
        target_branch_func(1); // Probe: expected taken, and is taken (correct prediction)
        asm volatile ("rdcycle %0" : "=r" (end));
        pc_predicted_taken[i] = end - start;

        // Train branch to always predict TAKEN again to ensure consistent state
        for (int j = 0; j < N_TRAIN_INITIAL; j++) {
            target_branch_func(1); // Force taken
        }

        asm volatile("nop; nop; nop; nop; nop; nop; nop; nop;"); // Pipeline settle
        asm volatile ("rdcycle %0" : "=r" (start));
        target_branch_func(0); // Probe: expected taken, but forced not taken (misprediction)
        asm volatile ("rdcycle %0" : "=r" (end));
        pc_mispredicted_not_taken[i] = end - start;
    }

    printf("Positive Control (Predicted Taken) Results:\n");
    for (int i = 0; i < N_TRIALS; i++) {
        printf("%lu\n", pc_predicted_taken[i]);
    }
    printf("Positive Control (Mispredicted Not Taken) Results:\n");
    for (int i = 0; i < N_TRIALS; i++) {
        printf("%lu\n", pc_mispredicted_not_taken[i]);
    }
    printf("--- End Positive Control (Branch Prediction Baseline) ---\n");


    // --- Attack Scenario Trials: TAGE U-Counter Manipulation ---
    // This section tests if the u-counter state, after de-training,
    // is affected by victim execution, leading to observable timing differences.
    printf("\n--- Attack Scenario: TAGE U-Counter Manipulation ---\n");

    for (int i = 0; i < N_TRIALS; i++) {
        // Scenario 1: U-Counter De-trained, Victim Does NOT Execute
        // Attacker de-trains the u-counter for target_branch_func.
        de_train_u_counter();
        // Victim performs unrelated work. The u-counter should remain at 0.
        victim_do_nothing();
        // Attacker probes. This probe is expected to be slower due to the u-counter being 0.
        results_neg_control[i] = probe_target_branch();

        // Scenario 2: U-Counter De-trained, Victim DOES Execute
        // Attacker de-trains the u-counter for target_branch_func again for a clean slate.
        de_train_u_counter();
        // Victim executes target_branch_func once. This should increment the u-counter.
        victim_execute_branch_once(); 
        // Attacker probes. This probe is expected to be faster due to the u-counter being > 0.
        results_pos_control[i] = probe_target_branch();
    }

    printf("Results (U-Counter De-trained, Victim NOT executes, then Probe):\n");
    for (int i = 0; i < N_TRIALS; i++) {
        printf("%lu\n", results_neg_control[i]);
    }

    printf("Results (U-Counter De-trained, Victim DOES execute, then Probe):\n");
    for (int i = 0; i < N_TRIALS; i++) {
        printf("%lu\n", results_pos_control[i]);
    }

    printf("--- End Attack Scenario (TAGE U-Counter Manipulation) ---\n");

    return 0;
}
